import { DomainError } from "@dawnstudio/core";
import Database from "better-sqlite3";
import { type BetterSQLite3Database, drizzle } from "drizzle-orm/better-sqlite3";
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import { readMigrationFiles } from "drizzle-orm/migrator";
import * as schema from "./schema";

export type Db = BetterSQLite3Database<typeof schema>;

export interface OpenDatabaseOptions {
	/** Path to the SQLite file, or ":memory:". */
	file: string;
	/** Folder with the SQL migrations generated by drizzle-kit. */
	migrationsFolder: string;
	/**
	 * Called before pending migrations run on a database that already has data, with a
	 * function that writes a consistent copy of it. Throwing stops the open (nothing migrated).
	 */
	beforeMigrate?: (info: { pending: number; snapshot: (destination: string) => void }) => void;
}

const MIGRATIONS_TABLE = "__drizzle_migrations";

/** Applied vs known migrations, as drizzle tracks them (by the migration folder's timestamp). */
export function migrationStatus(sqlite: Database.Database, migrationsFolder: string) {
	const known = readMigrationFiles({ migrationsFolder });
	const tracked = sqlite
		.prepare("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?")
		.get(MIGRATIONS_TABLE);
	const last = tracked
		? (sqlite.prepare(`SELECT max(created_at) AS at FROM ${MIGRATIONS_TABLE}`).get() as {
				at: number | null;
			})
		: { at: null };
	const lastApplied = last.at === null ? null : Number(last.at);
	const newest = Math.max(0, ...known.map((m) => m.folderMillis));
	const hasData =
		(
			sqlite.prepare("SELECT count(*) AS n FROM sqlite_master WHERE type = 'table'").get() as {
				n: number;
			}
		).n > 0;
	return {
		pending: known.filter((m) => lastApplied === null || m.folderMillis > lastApplied).length,
		/** Written by a newer version of the app: its tables may not match this version's code. */
		fromNewerVersion: lastApplied !== null && lastApplied > newest,
		hasData,
	};
}

/** Writes a compact, consistent copy of the open database (works while it's in use). */
const snapshotTo = (sqlite: Database.Database) => (destination: string) => {
	sqlite.prepare("VACUUM INTO ?").run(destination);
};

/** Opens the database and applies any pending migrations. */
export function openDatabase({ file, migrationsFolder, beforeMigrate }: OpenDatabaseOptions) {
	const sqlite = new Database(file);
	try {
		sqlite.pragma("journal_mode = WAL");
		sqlite.pragma("foreign_keys = ON");
		sqlite.pragma("busy_timeout = 5000");

		const status = migrationStatus(sqlite, migrationsFolder);
		if (status.fromNewerVersion) {
			throw new DomainError(
				"INVALID_STATE",
				"This data was saved by a newer version of Invoicing. Update the app to open it.",
			);
		}
		if (status.pending > 0 && status.hasData) {
			beforeMigrate?.({ pending: status.pending, snapshot: snapshotTo(sqlite) });
		}

		const db: Db = drizzle({ client: sqlite, schema, casing: "snake_case" });
		migrate(db, { migrationsFolder });

		return {
			db,
			snapshot: snapshotTo(sqlite),
			/** Runs SQLite's integrity check; "ok" when the file is sound. */
			integrityCheck: () => String(sqlite.pragma("integrity_check", { simple: true })),
			close: () => sqlite.close(),
		};
	} catch (error) {
		sqlite.close();
		throw error;
	}
}

export type OpenedDatabase = ReturnType<typeof openDatabase>;

/** The business name in a database file, read-only and without migrating it; null if unreadable. */
export function peekBusinessName(file: string): string | null {
	let sqlite: Database.Database | null = null;
	try {
		sqlite = new Database(file, { readonly: true, fileMustExist: true });
		const row = sqlite.prepare("SELECT name FROM business_profiles LIMIT 1").get() as
			| { name: string }
			| undefined;
		return row?.name || null;
	} catch {
		return null;
	} finally {
		sqlite?.close();
	}
}
